#!/usr/bin/env python3

import csv
import json
from copy import deepcopy
from dataclasses import dataclass
from datetime import datetime
from decimal import Decimal, ROUND_HALF_UP
from pathlib import Path
from typing import Any, Dict, Iterable, List, Tuple

ROOT = Path(__file__).resolve().parent

MANIFEST_PATH = ROOT / "assay_manifest.json"
CARRIER_COST_PATH = ROOT / "carrier_cost.csv"
BILLING_PATH = ROOT / "billing.csv"
LAB_OVERRIDES_PATH = ROOT / "lab_overrides.csv"
TEMPLATE_PATH = ROOT / "report_template.json"

OUT_REPORT_PATH = ROOT / "reagent_policy_report.json"
OUT_SUMMARY_PATH = ROOT / "reagent_policy_summary.md"


def _is_truthy(v: Any) -> bool:
    if isinstance(v, bool):
        return v
    if v is None:
        return False
    if isinstance(v, (int, float)):
        return v != 0
    if isinstance(v, str):
        return v.strip().lower() in {"true", "t", "yes", "y", "1"}
    return False


def _to_decimal(v: Any) -> Decimal:
    if isinstance(v, Decimal):
        return v
    if v is None:
        raise ValueError("Expected numeric value, got None")
    return Decimal(str(v).strip())


def _usd2(v: Decimal) -> Decimal:
    return v.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


def _usd2f(v: Decimal) -> float:
    return float(_usd2(v))


def _parse_month_yyyy_mm(s: str) -> Tuple[int, int]:
    ss = (s or "").strip()
    dt = datetime.strptime(ss, "%Y-%m")
    return dt.year, dt.month


def read_json(path: Path) -> Any:
    with path.open("r", encoding="utf-8") as f:
        return json.load(f)


def read_csv_dicts(path: Path) -> List[Dict[str, str]]:
    with path.open("r", encoding="utf-8", newline="") as f:
        return list(csv.DictReader(f))


def flatten_manifest_assays(manifest: Any) -> List[Dict[str, Any]]:
    """Return a flat list of assay dicts.

    Supports:
      - dict with key 'regions', where each region has key 'assays'
      - list of assays directly
      - dict of assays keyed by id/name
    """
    if isinstance(manifest, list):
        return [a for a in manifest if isinstance(a, dict)]

    if isinstance(manifest, dict):
        if "regions" in manifest and isinstance(manifest["regions"], list):
            assays: List[Dict[str, Any]] = []
            for region in manifest["regions"]:
                if not isinstance(region, dict):
                    continue
                region_assays = region.get("assays")
                if isinstance(region_assays, list):
                    assays.extend([a for a in region_assays if isinstance(a, dict)])
            return assays

        vals = [v for v in manifest.values() if isinstance(v, dict)]
        if vals:
            return vals

    raise ValueError("Unrecognized assay_manifest.json structure")


def build_carrier_cost_map(rows: List[Dict[str, str]]) -> Dict[str, Decimal]:
    out: Dict[str, Decimal] = {}
    for r in rows:
        ct = (r.get("carrier_type") or "").strip()
        if not ct:
            continue
        out[ct] = _to_decimal(r.get("carrier_cost_usd"))
    return out


@dataclass
class BillingRow:
    assay_label: str
    effective_month: str
    is_active: bool
    payment_per_run_per_lab_usd: Decimal


def parse_billing_rows(rows: List[Dict[str, str]]) -> List[BillingRow]:
    out: List[BillingRow] = []
    for r in rows:
        out.append(
            BillingRow(
                assay_label=(r.get("assay_label") or "").strip(),
                effective_month=(r.get("effective_month") or "").strip(),
                is_active=_is_truthy(r.get("is_active")),
                payment_per_run_per_lab_usd=_to_decimal(r.get("payment_per_run_per_lab_usd")),
            )
        )
    return out


def resolve_billing_payment(
    assay_name: str, aliases: Iterable[str], billing_rows: List[BillingRow]
) -> Decimal:
    labels = {assay_name}
    for a in aliases or []:
        if a is None:
            continue
        aa = str(a).strip()
        if aa:
            labels.add(aa)

    matches = [r for r in billing_rows if r.assay_label in labels and r.is_active]
    if not matches:
        raise ValueError(
            f"No active billing row found for assay_name={assay_name!r} labels={sorted(labels)!r}"
        )

    best = max(matches, key=lambda r: _parse_month_yyyy_mm(r.effective_month))
    return best.payment_per_run_per_lab_usd


def resolve_active_labs(
    assay_id: str,
    default_active_labs: Any,
    override_rows: List[Dict[str, str]],
) -> int:
    # Prefer exact 'approved'; if none exist at all, allow case-insensitive.
    exact_any = any((r.get("status") or "").strip() == "approved" for r in override_rows)

    if exact_any:
        approved = [
            r
            for r in override_rows
            if (r.get("status") or "").strip() == "approved"
            and (r.get("assay_id") or "").strip() == assay_id
        ]
    else:
        approved = [
            r
            for r in override_rows
            if (r.get("status") or "").strip().lower() == "approved"
            and (r.get("assay_id") or "").strip() == assay_id
        ]

    if approved:
        def rev_num(r: Dict[str, str]) -> int:
            try:
                return int((r.get("revision") or "0").strip())
            except ValueError:
                return 0

        best = max(approved, key=rev_num)
        if "active_labs" in best and (best.get("active_labs") or "").strip() != "":
            return int(best["active_labs"])
        if "lab_count" in best and (best.get("lab_count") or "").strip() != "":
            return int(best["lab_count"])
        raise ValueError(f"Approved override row missing lab count for assay_id={assay_id}")

    return int(default_active_labs)


def main() -> None:
    manifest = read_json(MANIFEST_PATH)
    carrier_cost_rows = read_csv_dicts(CARRIER_COST_PATH)
    billing_rows_raw = read_csv_dicts(BILLING_PATH)
    override_rows = read_csv_dicts(LAB_OVERRIDES_PATH)
    template = read_json(TEMPLATE_PATH)

    assays_all = flatten_manifest_assays(manifest)
    assays_in_scope = [a for a in assays_all if _is_truthy(a.get("in_scope"))]

    carrier_cost_by_type = build_carrier_cost_map(carrier_cost_rows)
    billing_rows = parse_billing_rows(billing_rows_raw)

    per_assay_entries: List[Dict[str, Any]] = []

    total_small = Decimal("0")
    total_bulk = Decimal("0")
    total_diff = Decimal("0")

    for a in sorted(assays_in_scope, key=lambda x: str(x.get("assay_id", ""))):
        assay_id = str(a.get("assay_id") or "").strip()
        assay_name = str(a.get("assay_name") or "").strip()
        aliases = a.get("aliases") or []
        carrier_type = str(a.get("carrier_type") or "").strip()

        if not assay_id or not assay_name:
            raise ValueError(f"Assay missing assay_id/assay_name: {a}")

        payment = resolve_billing_payment(assay_name, aliases, billing_rows)
        active_labs = resolve_active_labs(
            assay_id=assay_id,
            default_active_labs=a.get("default_active_labs"),
            override_rows=override_rows,
        )

        if carrier_type not in carrier_cost_by_type:
            raise ValueError(
                f"No carrier cost for carrier_type={carrier_type!r} (assay_id={assay_id})"
            )
        carrier_cost = carrier_cost_by_type[carrier_type]

        reagent_price_per_1000 = _to_decimal(a.get("reagent_price_per_1000_tests_usd"))
        tests_small = int(a.get("tests_per_lab_per_run_small"))
        tests_bulk = int(a.get("tests_per_lab_per_run_bulk"))

        runs_small = 24
        runs_bulk = 12

        annual_revenue_small = payment * Decimal(active_labs) * Decimal(runs_small)
        annual_revenue_bulk = payment * Decimal(active_labs) * Decimal(runs_bulk)

        annual_reagent_cost_small = (
            reagent_price_per_1000
            * Decimal(active_labs)
            * Decimal(tests_small)
            * Decimal(runs_small)
            / Decimal("1000")
        )
        annual_reagent_cost_bulk = (
            reagent_price_per_1000
            * Decimal(active_labs)
            * Decimal(tests_bulk)
            * Decimal(runs_bulk)
            / Decimal("1000")
        )

        # Carrier cost interpretation: per shipment (per lab per run)
        annual_carrier_cost_small = carrier_cost * Decimal(active_labs) * Decimal(runs_small)
        annual_carrier_cost_bulk = carrier_cost * Decimal(active_labs) * Decimal(runs_bulk)

        annual_margin_small = (
            annual_revenue_small - annual_reagent_cost_small - annual_carrier_cost_small
        )
        annual_margin_bulk = (
            annual_revenue_bulk - annual_reagent_cost_bulk - annual_carrier_cost_bulk
        )
        annual_diff = annual_margin_bulk - annual_margin_small

        total_small += annual_margin_small
        total_bulk += annual_margin_bulk
        total_diff += annual_diff

        per_assay_entries.append(
            {
                "assay_id": assay_id,
                "assay_name": assay_name,
                "carrier_type": carrier_type,
                "active_labs": active_labs,
                "payment_per_run_per_lab_usd": _usd2f(payment),
                "reagent_price_per_1000_tests_usd": _usd2f(reagent_price_per_1000),
                "carrier_cost_usd": _usd2f(carrier_cost),
                "tests_per_lab_per_run_small": tests_small,
                "tests_per_lab_per_run_bulk": tests_bulk,
                "annual_revenue_small_kit_usd": _usd2f(annual_revenue_small),
                "annual_revenue_bulk_kit_usd": _usd2f(annual_revenue_bulk),
                "annual_reagent_cost_small_kit_usd": _usd2f(annual_reagent_cost_small),
                "annual_reagent_cost_bulk_kit_usd": _usd2f(annual_reagent_cost_bulk),
                "annual_carrier_cost_small_kit_usd": _usd2f(annual_carrier_cost_small),
                "annual_carrier_cost_bulk_kit_usd": _usd2f(annual_carrier_cost_bulk),
                "annual_margin_small_kit_usd": _usd2f(annual_margin_small),
                "annual_margin_bulk_kit_usd": _usd2f(annual_margin_bulk),
                "annual_margin_difference_bulk_minus_small_usd": _usd2f(annual_diff),
            }
        )

    totals = {
        "total_annual_margin_small_kit_usd": _usd2f(total_small),
        "total_annual_margin_bulk_kit_usd": _usd2f(total_bulk),
        "total_annual_margin_difference_bulk_minus_small_usd": _usd2f(total_diff),
        "absolute_total_margin_difference_usd": _usd2f(abs(total_diff)),
    }

    abs_diff = abs(_usd2(total_diff))
    threshold = Decimal("7000")
    if abs_diff < threshold:
        decision = "adopt_bulk_kit"
        justification = (
            f"Absolute total annual margin difference (${_usd2(abs_diff)}) is below "
            f"the switch threshold (${_usd2(threshold)}), so adopt bulk kit."
        )
    else:
        decision = "keep_small_kit"
        justification = (
            f"Absolute total annual margin difference (${_usd2(abs_diff)}) meets/exceeds "
            f"the switch threshold (${_usd2(threshold)}), so keep small kit."
        )

    report = deepcopy(template)
    report["metadata"] = template["metadata"]  # exact

    if "analysis" not in report or not isinstance(report["analysis"], dict):
        report["analysis"] = {}

    report["analysis"]["assumptions"] = {
        "runs_per_year_small_kit": 24,
        "runs_per_year_bulk_kit": 12,
        "switch_threshold_usd": 7000,
        "lab_override_rule": "highest approved revision per assay_id, else default_active_labs",
        "billing_rule": "latest active effective_month per assay",
    }
    report["analysis"]["assays"] = per_assay_entries
    report["analysis"]["totals"] = totals
    report["analysis"]["recommendation"] = {
        "decision": decision,
        "justification": justification,
    }

    with OUT_REPORT_PATH.open("w", encoding="utf-8") as f:
        json.dump(report, f, indent=2)
        f.write("\n")

    summary_lines = [
        f"Total annual margin (small kit): ${totals['total_annual_margin_small_kit_usd']:.2f}",
        f"Total annual margin (bulk kit): ${totals['total_annual_margin_bulk_kit_usd']:.2f}",
        f"Absolute difference: ${totals['absolute_total_margin_difference_usd']:.2f}",
        f"Decision: {decision}",
        f"Justification: {justification}",
    ]

    with OUT_SUMMARY_PATH.open("w", encoding="utf-8") as f:
        f.write("\n".join(summary_lines) + "\n")


if __name__ == "__main__":
    main()

