            reagent_price_per_1000
            * Decimal(active_labs)
            * Decimal(tests_small)
            * Decimal(runs_small)
            / Decimal("1000")
        )
        annual_reagent_cost_bulk = (
            reagent_price_per_1000
            * Decimal(active_labs)
            * Decimal(tests_bulk)
            * Decimal(runs_bulk)
            / Decimal("1000")
        )

        # Carrier cost interpretation: per shipment (per lab per run)
        annual_carrier_cost_small = carrier_cost * Decimal(active_labs) * Decimal(runs_small)
        annual_carrier_cost_bulk = carrier_cost * Decimal(active_labs) * Decimal(runs_bulk)

        annual_margin_small = (
